// <auto-generated/>

using System.Configuration;

namespace Fanex.Tarus.Finance.Controller.Transfer
{
    using Fanex.Tarus.Finance.Business.Transfer;
    using Fanex.Tarus.Finance.Model.Transfer;
    using Fanex.Tarus.Web.Controllers;
    using Sunplus.Accounting.Business.Security;
    using Sunplus.Accounting.Core.Common;
    using System;
    using System.Net;
    using System.Web.Mvc;

    public class CrossTransferController : BaseController
    {
        private readonly ICrossTransferService crossTransferService;
        private readonly string RewardPromotionCode = ConfigurationManager.AppSettings["RewardPromotionCode"];
        private readonly string RewardPromotionID = ConfigurationManager.AppSettings["RewardPromotionID"];
        public CrossTransferController()
            : this(null)
        {
        }

        internal CrossTransferController(ICrossTransferService crossTransferService)
            => this.crossTransferService = crossTransferService ?? new CrossTransferService();

        public ActionResult Index()
        {
            string fromAmount = Request["fromAmount"] as string ?? string.Empty;
            string fromCustName = Request["fromCustName"] as string ?? string.Empty;
            string RewardCurrency = Request["RewardCurrency"] as string ?? string.Empty;
            string rewardMaxTransId = Request["RewardMaxTransId"] as string ?? string.Empty;
            string RewardAmount = Request["RewardAmount"] as string ?? string.Empty;
            bool IsShowReward = !string.IsNullOrEmpty(RewardAmount);
            double RewardAmountValue = string.IsNullOrEmpty(RewardAmount) ? 0.0 : Convert.ToDouble(RewardAmount) * -1;
            double AmountValue = string.IsNullOrEmpty(fromAmount) ? 0.0 : Convert.ToDouble(fromAmount) * -1;
            double rewardRate =  crossTransferService.SelectCustomerExRate(fromCustName).actualrate;
            double ExpensiseAmount = string.IsNullOrEmpty(RewardAmount) ? 0.0 : Convert.ToDouble(RewardAmount) * rewardRate;
            double total_YesterdayBalance_RewardPending = !IsShowReward ? 0.0 : RewardAmountValue + AmountValue;
            var crossTransferModel = new CrossTransfer
            {
                IsHadPermissionOnCrossCurrencyTransfer = Permissions.HasPermission("FinanceTransfer"),
                IsHadPermissionOnYesterdayTransfer = Permissions.HasPermission("OtherTrans"),
                FromAmount = AmountValue == 0.0 ? "0.00" : IBCUtils.FormatHandler.FormatNumber20(AmountValue),
                FromCustName = fromCustName,
                RewardCurrency = RewardCurrency,
                ForexAccount = Fanex.Tarus.Infrastructure.Caching.CacheHelper.Get<string>("Transfer_ForexAccount_" + AppSession.AccUserName),
                IsShowReward = IsShowReward,
                RewardMaxTransId = rewardMaxTransId,
                RewardAmount = RewardAmountValue == 0.0 ? "0.00" : IBCUtils.FormatHandler.FormatNumber20(RewardAmountValue),
                ExpensiseAmount = ExpensiseAmount == 0.0 ? "0.00" : IBCUtils.FormatHandler.FormatNumber20(ExpensiseAmount),
                Total_YesterdayBalance_RewardPending = IBCUtils.FormatHandler.FormatNumber20(total_YesterdayBalance_RewardPending),
                RewardExrate = IBCUtils.FormatHandler.FormatNumber20(rewardRate),
                RewardCode = RewardPromotionCode
            };

            if (!crossTransferModel.IsHadPermissionOnCrossCurrencyTransfer && !crossTransferModel.IsHadPermissionOnYesterdayTransfer)
            {
                return View("~/Views/Common/AccessDenied.cshtml");
            }

            return View("~/Views/Finance/Transfer/Index.cshtml", crossTransferModel);
        }

        public JsonResult TransferYesterdayTransactionHandler(TransferYesterdayTransaction request)
        {
            request.FromCustName = WebUtility.HtmlDecode(request.FromCustName);
            request.ToCustName = WebUtility.HtmlDecode(request.ToCustName);
            if (request.IsShowReward)
            {
                request.RewardCustId = Convert.ToInt32(RewardPromotionID);
            }

            return Json(crossTransferService.TransferYesterdayTransaction(request), JsonRequestBehavior.AllowGet);
        }

        public JsonResult SelectCustomerExRate(string username)
        {
            username = WebUtility.HtmlDecode(username);

            return Json(crossTransferService.SelectCustomerExRate(username), JsonRequestBehavior.AllowGet);
        }

        public JsonResult CrossCurrencyTransferInsert(FinanceCrossCurrencyTransfer request)
            => Json(crossTransferService.CrossCurrencyTransferInsert(request), JsonRequestBehavior.AllowGet);

        public JsonResult SelectAllForexAccount()
            => Json(crossTransferService.SelectAllForexAccount(), JsonRequestBehavior.AllowGet);
    }
}